    public static METSalesOrderReturnCreditRegistrationResponseContract newFromParameters(METProcessingStatus _result, Description255 _message)
    {
        METSalesOrderReturnCreditRegistrationResponseContract response = new METSalesOrderReturnCreditRegistrationResponseContract();

        response.parmResult(enum2Symbol(enumNum(METProcessingStatus), enum2int(_result)));
